import sys
from collections import defaultdict

def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)

def process_shift(in_time, out_time):
    in_min = minutes(in_time)
    out_min = minutes(out_time)
    if out_min < in_min:
        out_min += 24 * 60
    worked = out_min - in_min
    if worked > 6 * 60:
        if worked > 9 * 60:
            worked -= 45
        else:
            worked -= 30
    return worked

def main():
    employee_shifts = defaultdict(list)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, in_time, out_time = line.split()
        worked = process_shift(in_time, out_time)
        employee_shifts[name].append(worked)

    total_paid = defaultdict(int)
    for name, shifts in employee_shifts.items():
        total = sum(shifts)
        total_paid[name] = total

    sorted_names = sorted(total_paid.keys())
    for name in sorted_names:
        h = total_paid[name] // 60
        m = total_paid[name] % 60
        print(f"{name} {h}:{m:02d}")


if __name__ == "__main__":
    main()
